import hashlib, os, time, re
from datetime import datetime, timezone

CACHE_DIR = os.environ.get('PALM_DOC_CACHE', '/tmp/palm_doc_cache')
HEADERS = {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36',
    'Accept': 'text/html,application/pdf,*/*',
    'Accept-Language': 'en-US,en;q=0.9',
}
WAYBACK = 'https://web.archive.org/web/2/'

def _get(url, retries=3):
    import requests
    for i in range(retries):
        try:
            r = requests.get(url, headers=HEADERS, timeout=45, stream=True)
            if r.status_code == 200:
                return r.content, 'ok'
            if r.status_code in (401, 403):
                return None, 'blocked'
            if r.status_code == 404:
                return None, 'missing'
        except Exception:
            pass
        time.sleep(2 ** i)
    return None, 'missing'

def _extract_text(raw):
    if raw[:4] == b'%PDF' or raw[:4] == b'\x25PDF':
        import io
        from pdfminer.high_level import extract_text
        return extract_text(io.BytesIO(raw))
    import html2text
    return html2text.html2text(raw.decode('utf-8', errors='replace'))

def _parse_year_type(text):
    year = None
    audit_type = None
    m = re.search(r'(20\d{2})', text[:2000] if text else '')
    if m:
        year = int(m.group(1))
    if 'recertification' in (text or '').lower():
        audit_type = 'recertification'
    elif 'annual surveillance' in (text or '').lower():
        audit_type = 'annual_surveillance'
    elif 'initial' in (text or '').lower()[:500]:
        audit_type = 'initial'
    return year, audit_type

def transform(row):
    row = dict(row)
    url = row.get('url') or ''
    os.makedirs(CACHE_DIR, exist_ok=True)
    sha_key = hashlib.sha256(url.encode()).hexdigest()
    cache_path = os.path.join(CACHE_DIR, sha_key)
    if os.path.exists(cache_path):
        with open(cache_path, 'rb') as f:
            raw = f.read()
        status = 'ok'
    else:
        raw, status = _get(url)
        if raw is None and status == 'missing':
            raw, wb_status = _get(WAYBACK + url)
            if raw is not None:
                status = 'wayback_fallback'
        if raw is not None:
            with open(cache_path, 'wb') as f:
                f.write(raw)
    if raw is None:
        row['retrieval_status'] = status
        row['retrieval_timestamp'] = None
        row['raw_bytes_hash'] = None
        row['extracted_text'] = None
        row['audit_year'] = None
        row['audit_type'] = None
    else:
        text = _extract_text(raw)
        year, atype = _parse_year_type(text)
        row['retrieval_status'] = status
        row['retrieval_timestamp'] = datetime.now(timezone.utc).isoformat()
        row['raw_bytes_hash'] = hashlib.sha256(raw).hexdigest()
        row['extracted_text'] = text
        row['audit_year'] = year
        row['audit_type'] = atype
    return row

import json

def transform(df):
    import pandas as pd
    rows = []
    for mill_id, grp in df.groupby('facility_uml_id'):
        docs = []
        for _, r in grp.iterrows():
            docs.append({
                'document_id': r['document_id'],
                'document_type': r['document_type'],
                'url': r.get('url'),
                'audit_year': r.get('audit_year'),
                'audit_type': r.get('audit_type'),
                'source_grade': r['source_grade'],
                'retrieval_status': r['retrieval_status'],
            })
        rows.append({'facility_uml_id': mill_id, 'docs': json.dumps(docs)})
    return pd.DataFrame(rows)

def transform(docs_df, sel_df):
    import pandas as pd
    sel = sel_df.set_index('facility_uml_id')[['authoritative_rspo_id', 'authoritative_cdm_id']].to_dict('index')
    result = []
    for _, row in docs_df.iterrows():
        mill_sel = sel.get(row['facility_uml_id'], {})
        auth_ids = {mill_sel.get('authoritative_rspo_id'), mill_sel.get('authoritative_cdm_id')} - {None}
        if row['document_id'] in auth_ids:
            r = dict(row)
            r['is_authoritative'] = True
            result.append(r)
    return pd.DataFrame(result) if result else pd.DataFrame(columns=docs_df.columns)

